//! Translations. The key is the Ukrainian text, values are translations by language code.
//! web/i18n.json is generated by tools/i18n_src.py. Only the current language is kept in memory.

use std::{
    collections::HashMap,
    sync::{LazyLock, RwLock},
};

use serde::{Deserialize, Serialize};

const I18N_JSON: &str = include_str!("../../web/i18n.json");

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Lang {
    pub code: String,
    pub name: String,
}

#[derive(Deserialize)]
struct Langs {
    langs: Vec<Lang>,
}

#[derive(Deserialize)]
struct Strings {
    strings: HashMap<String, HashMap<String, String>>,
}

pub static LANGS: LazyLock<Vec<Lang>> =
    LazyLock::new(|| serde_json::from_str::<Langs>(I18N_JSON).map(|x| x.langs).unwrap_or_default());

struct Tab {
    code: String,
    t: HashMap<String, String>,
}

static CUR: RwLock<Option<Tab>> = RwLock::new(None);

/// All translations of all languages (parsed anew: needed only when the language changes).
pub fn all_strings() -> HashMap<String, HashMap<String, String>> {
    serde_json::from_str::<Strings>(I18N_JSON).map(|x| x.strings).unwrap_or_default()
}

/// Makes a language current (only its translations stay in memory).
pub fn set_lang(code: &str) {
    let mut t = HashMap::new();
    if code != "uk" {
        for (k, m) in all_strings() {
            if let Some(v) = m.get(code).filter(|v| !v.is_empty()) {
                t.insert(k, v.clone());
            }
        }
    }
    *CUR.write().unwrap() = Some(Tab { code: code.to_string(), t });
}

pub fn supported(code: &str) -> bool {
    LANGS.iter().any(|l| l.code == code)
}

/// The user's pick, otherwise the Windows language, otherwise English.
pub fn resolve(pick: &str, system: &str) -> String {
    if !pick.is_empty() && supported(pick) {
        pick.to_string()
    } else if supported(system) {
        system.to_string()
    } else {
        "en".to_string()
    }
}

pub fn lang() -> String {
    CUR.read().unwrap().as_ref().map(|t| t.code.clone()).unwrap_or_else(|| "uk".into())
}

/// Translates Ukrainian text into the current language (as is when there is no translation).
pub fn t(s: &str) -> String {
    CUR.read().unwrap().as_ref().and_then(|tab| tab.t.get(s).cloned()).unwrap_or_else(|| s.to_string())
}

/// What the window page gets: current language, the user's pick, languages and the dictionary.
pub fn payload(pick: &str) -> String {
    let g = CUR.read().unwrap();
    let (code, t) = match g.as_ref() {
        Some(tab) => (tab.code.clone(), tab.t.clone()),
        None => ("uk".to_string(), HashMap::new()),
    };
    serde_json::json!({ "lang": code, "pick": pick, "langs": *LANGS, "t": t }).to_string()
}

/// Windows UI language (primary LANGID).
pub fn system_lang() -> &'static str {
    let id = unsafe { windows::Win32::Globalization::GetUserDefaultUILanguage() };
    match id & 0x3ff {
        0x22 => "uk",
        0x09 => "en",
        0x07 => "de",
        0x0c => "fr",
        0x0a => "es",
        0x16 => "pt",
        0x15 => "pl",
        0x10 => "it",
        0x1f => "tr",
        _ => "",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lookup_and_resolve() {
        assert!(LANGS.len() >= 9);
        assert_eq!(resolve("", "de"), "de");
        assert_eq!(resolve("", "ru"), "en");
        assert_eq!(resolve("pl", "de"), "pl");
        set_lang("de");
        assert_eq!(t("Налаштування"), "Einstellungen");
        assert_eq!(t("невідомий рядок"), "невідомий рядок");
        assert!(payload("").contains("\"lang\":\"de\""));
        set_lang("uk");
    }

    /// Translations keep the same format verbs (%d, %%) as the original.
    #[test]
    fn format_verbs() {
        let verbs = |s: &str| (s.matches("%d").count(), s.replace("%%", "\0").matches('\0').count());
        for (k, m) in all_strings() {
            for (l, v) in m {
                assert_eq!(verbs(&v), verbs(&k), "{l}: {k:?} -> {v:?}");
            }
        }
    }
}
